-- Só espelha global que existe nesse cliente. Não cria coisa nova à toa.
do
    local source = AscensionPTBR.UIStrings or {}
    local active, byEnglish = {}, {}
    for key, translated in pairs(source) do
        local english = type(key) == "string" and rawget(_G, key) or nil
        if type(english) == "string" and english ~= "" and type(translated) == "string" then
            active[key] = translated
            local prior = byEnglish[english]
            if prior == nil then
                byEnglish[english] = translated
            elseif prior ~= translated then
                byEnglish[english] = false
            end
        end
    end
    for english, translated in pairs(byEnglish) do
        if translated == false then byEnglish[english] = nil end
    end
    AscensionPTBR.UIStrings = active
    AscensionPTBR.UIStringsByEN = byEnglish
end


local A = AscensionPTBR
